#define rgbTimeOffset (0.05)
#define PI 3.14159

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // normalize uv and scale resolution
    vec2 r = iResolution.xy;
    vec2 res = vec2(r.x / r.y, 1.0);
    vec2 uv = fragCoord / r.y;

    vec2 center = vec2(0.5) * res;

    // params
    float scale = 0.9;
    float oWidth = 0.5;
    float ringW = 0.0025;
    float nRings = 25.0;
    float twirlAmt = 0.3;
    twirlAmt = 0.0;
    float perspectiveAmt = 1.0 / nRings / 2.0;

    // code
    vec3 C;
#ifdef rgbTimeOffset
    for (float ti = 0.0; ti < 3.0; ti++) {
        float t = iTime + ti * rgbTimeOffset;
#else
    float t = iTime;
#endif

    float pixelWidth = 1.0 / r.y;
    float blur = 1.5 / r.y;

    float intensity = 0.0;
    for (float i = 0.0; i < nRings; i++) {
        float twirl = i * twirlAmt * sin(iTime / 20.0);
        float angle = t + twirl;

        if (iMouse.z > 0.0) {
            vec2 mousePos = iMouse.xy / r.y;
            vec2 relMouse = mousePos - center;
            float mouseAngle = atan(relMouse.y, relMouse.x);
            angle = PI + mouseAngle;
            float distFactor = length(relMouse) * 2.0;
            perspectiveAmt = .01/distFactor;
        }

        float cosA = cos(angle);
        float sinA = sin(angle);
        mat2 rot = mat2(cosA, -sinA, sinA, cosA);

        float band = oWidth * pow(scale, i);
        vec2 uv2 = uv;
        // offsetting the offset creates funky perspective effect
        float perspectiveShift = i * perspectiveAmt;
        float off = band - oWidth + perspectiveShift;
        uv2 -= vec2(off, 0.0) * rot;

        intensity += 1.0 - smoothstep(band - blur, band + blur, distance(uv2, center));
        intensity -= 1.0 - smoothstep(band - ringW - blur, band - ringW + blur, distance(uv2, center));
    }
#ifdef rgbTimeOffset
    C[int(ti)] = intensity;
    }
#else
    C = vec3(intensity);
    C *= 0.5 + 0.5 * cos(iTime + uv.xyx + vec3(0, 2, 4));
#endif

    // Output to screen
    fragColor = vec4(C, 1.0);
}
